const dbRecord = $('Loop: oferta por oferta').item.json;
const dbId     = String(dbRecord.id     || '');
const dbUrl    = String(dbRecord.url    || '');
const dbPortal = String(dbRecord.portal || '');

const httpOut = $input.item.json;
const html    = typeof httpOut === 'string' ? httpOut
  : (httpOut.data || httpOut.body || httpOut.html || '');
const htmlStr = String(html);

console.log('[enrich-color] id=' + dbId + ' portal=' + dbPortal + ' html_len=' + htmlStr.length);

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') return isNaN(v) ? 'NULL' : String(v);
  return "'" + String(v).replace(/'/g, "''") + "'";
}

if (!dbId || htmlStr.length < 500) {
  // HTML vacío o petición fallida — marcar enrich_tried_at para no reintentar hoy
  await new Promise(r => setTimeout(r, 300));
  const sql = 'UPDATE moveadvisor_market_offers SET enrich_tried_at = NOW(), updated_at = NOW() WHERE id = ' + esc(dbId);
  return [{ json: { id: dbId, colorFound: false, updateSql: dbId ? sql : null } }];
}

let colorVal = '';
let buildId  = '';

// ── ESTRATEGIA 1: JSON-LD (application/ld+json) ───────────────────────────
// Funciona en: Autocasion, Coches.com, Coches.net, AutoScout24, CanalCar, OcasionPlus, Clicars, Wallapop, Milanuncios…
try {
  const blocks = [...htmlStr.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)].map(m => m[1].trim());
  for (const b of blocks) {
    try {
      const j = JSON.parse(b);
      const arr = Array.isArray(j) ? j : (j['@graph'] || [j]);
      for (const o of arr) {
        if (!o || (o['@type'] !== 'Car' && o['@type'] !== 'Product')) continue;
        const car = (o.offers && o.offers.itemOffered) || o;
        const c = car.color || o.color || car.colour || o.colour
          || car.colorName || o.colorName || car.exteriorColor || o.exteriorColor || '';
        if (c) { colorVal = c; break; }
      }
      if (colorVal) break;
    } catch(e) {}
  }
  if (colorVal) console.log('[enrich-color] JSON-LD color=' + colorVal);
} catch(e) {
  console.log('[enrich-color] JSON-LD error: ' + e.message);
}

// ── ESTRATEGIA 2: __NEXT_DATA__ (Next.js SSR) ─────────────────────────────
// Funciona en: Flexicar, Autohero, y otros portales Next.js
if (!colorVal) {
  try {
    const ndMatch = htmlStr.match(/<script id="__NEXT_DATA__" type="application\/json">([\s\S]*?)<\/script>/);
    if (ndMatch) {
      const nd  = JSON.parse(ndMatch[1]);
      buildId   = nd.buildId || '';
      const pp  = (nd.props || {}).pageProps || {};

      let v = pp.vehicle || pp.car || pp.data || pp.offer || pp.vehicleData || pp.detail || null;
      if (!v) {
        const is = (nd.props || {}).initialState || {};
        v = is.vehicle || is.car || null;
      }
      // TanStack / React Query dehydratedState
      if (!v && pp.dehydratedState) {
        const queries = (pp.dehydratedState.queries || []);
        for (const q of queries) {
          const d = (q.state || {}).data;
          if (!d) continue;
          if (d.color !== undefined || d.brand !== undefined) { v = d; break; }
          const nested = d.vehicle || d.car || d.data || null;
          if (nested && (nested.color !== undefined || nested.brand !== undefined)) { v = nested; break; }
          if (Array.isArray(d) && d.length > 0 && d[0].brand !== undefined) { v = d[0]; break; }
        }
      }
      if (v) {
        colorVal = v.color || v.colorName || v.colour || v.colorExterior
          || v.colorValue || v.exteriorColor || v.paintColor || '';
        if (colorVal) console.log('[enrich-color] __NEXT_DATA__ color=' + colorVal);
      }
    }
  } catch(e) {
    console.log('[enrich-color] __NEXT_DATA__ error: ' + e.message);
  }
}

// ── ESTRATEGIA 3: _next/data JSON (solo Flexicar, si buildId disponible) ──
if (!colorVal && dbPortal === 'flexicar' && buildId && dbUrl) {
  try {
    const slug    = dbUrl.split('/').filter(Boolean).pop() || '';
    const jsonUrl = 'https://www.flexicar.es/_next/data/' + buildId + '/coches-ocasion/' + slug + '.json';
    console.log('[enrich-color] flexicar _next/data: ' + jsonUrl);
    const jr   = await $helpers.httpRequest({
      method: 'GET',
      url: jsonUrl,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36',
        'Accept': 'application/json'
      }
    });
    const jRaw = typeof jr === 'string' ? JSON.parse(jr) : jr;
    const jpp  = (jRaw && jRaw.pageProps) ? jRaw.pageProps : {};
    const jv   = jpp.vehicle || jpp.car || jpp.data || jpp.offer || jpp.vehicleData || null;
    if (jv) {
      colorVal = jv.color || jv.colorName || jv.colour || jv.colorExterior
        || jv.colorValue || jv.exteriorColor || '';
      console.log('[enrich-color] flexicar _next/data color=' + colorVal);
    } else {
      console.log('[enrich-color] flexicar _next/data pp keys=' + Object.keys(jpp).join(','));
    }
  } catch(e) {
    console.log('[enrich-color] flexicar _next/data error: ' + e.message);
  }
}

// ── ESTRATEGIA 4: Regex genérico ──────────────────────────────────────────
if (!colorVal) {
  // Intento 1: campo JSON "color":"..."
  const m1 = htmlStr.match(/"color"\s*:\s*"([^"]{2,40})"/i);
  if (m1) colorVal = m1[1];
}
if (!colorVal) {
  // Intento 2: etiqueta HTML con texto de color
  const m2 = htmlStr.match(/[Cc]olor[^>]{0,60}>([A-ZÁÉÍÓÚÜÑ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ\s]{1,25})<\//);
  if (m2) colorVal = m2[1].trim();
}
if (colorVal) console.log('[enrich-color] regex fallback color=' + colorVal);

console.log('[enrich-color] FINAL portal=' + dbPortal + ' color=' + colorVal);

// ── SQL ────────────────────────────────────────────────────────────────────
const sets = ['enrich_tried_at = NOW()'];
if (colorVal) sets.push('color = COALESCE(NULLIF(color,\'\'), ' + esc(colorVal) + ')');

const updateSql = 'UPDATE moveadvisor_market_offers SET '
  + sets.join(', ') + ', updated_at = NOW() WHERE id = ' + esc(dbId);

await new Promise(r => setTimeout(r, 600));
return [{ json: { id: dbId, colorFound: !!colorVal, updateSql: updateSql } }];
